#!/usr/bin/env python3
"""Stage second-pass WhatsApp video OCR ads into manual_ads.json.

Generated by ChatGPT after a denser OCR pass over the uploaded screen recording.
The merge workflow runs this script, then merge_manual_ads.py folds the records
into real_estate_ads.json and deletes manual_ads.json.
"""
from __future__ import annotations
import base64
import zlib
from pathlib import Path

BATCH_ZLIB_B64 = """"""

ROOT = Path(__file__).resolve().parent
MANUAL = ROOT / "manual_ads.json"


def main() -> int:
    raw = zlib.decompress(base64.b64decode(BATCH_ZLIB_B64.encode("ascii")))
    MANUAL.write_bytes(raw)
    print(f"Staged second OCR batch into {MANUAL.name} ({len(raw)} bytes)")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
